 const show=name=>{app.querySelectorAll(".l2-section").forEach(x=>x.classList.toggle("active",x.dataset.l2Panel===name));app.querySelectorAll(".l2-tab").forEach(x=>x.classList.toggle("active",x.dataset.l2Section===name));state.answers.l2_tab=name;saveState();window.scrollTo(0,0)};
