 const teacherPrompt=(task,title,html,kind="talk")=>{if(!task)return;const box=document.createElement("aside");box.className=`one-to-one-prompt ${kind}`;box.innerHTML=`<strong>${title}</strong>${html}`;task.append(box)};
 const tasks=[...app.querySelectorAll(".lesson-two .task")];tasks.forEach(task=>activityLabel(task,"solo"));
 const character=app.querySelector(".character-snap");teacherPrompt(character,"🗣 Talk to your teacher",`<p>Explain your choice.</p><p class="sentence-frame">I chose this person because… · Their posture looks… · They seem…</p>`);
 const impression=app.querySelector(".first-impression");teacherPrompt(impression,"🗣 Talk to your teacher",`<p>Give one reason for your answer.</p><small><b>Teacher prompt:</b> What else would you need to know about this person?</small>`);
 const wordCards=[...app.querySelectorAll(".meet-word-card")];[[2,"Choose one new adjective and explain it without using the definition."],[5,"Give your own example of a reliable, stubborn or sociable person."]].forEach(([i,p])=>teacherPrompt(wordCards[i],"🗣 Quick Teacher Check",`<p>${p}</p>`,"quick"));
 const quickRecall=app.querySelector('[data-task="l2_quick_recall"]');activityLabel(quickRecall,"solo");
 const spectrumTask=app.querySelector('[data-task="l2_spectrum"]');teacherPrompt(spectrumTask,"🗣 Talk to your teacher",`<p>Choose TWO adjectives and explain why you placed them there.</p><small><b>Teacher prompts:</b> Can this quality be useful in another situation? Can it cause problems? Can you give an example?</small>`);
 const stubborn=app.querySelector(".stubborn-note");teacherPrompt(stubborn,"🗣 Talk to your teacher",`<p>Give one situation where being stubborn could help someone.</p>`);
 const oppositePuzzle=app.querySelector('[data-task="l2_opposites"]');teacherPrompt(oppositePuzzle,"🗣 Quick Teacher Check",`<p>Choose one pair and make two short sentences.</p><small>Example: Tom is patient. His brother is impatient.</small>`,"quick");
